// FUNCIÓN ITERATIVA PARA CALCULAR LA POTENCIA...

double potenciaIterativa(double base, int exponente)
{
    double resultado = 1;
    bool negativo = false;

    if (exponente < 0)
    {
        negativo = true;
        exponente = -exponente;
    }

    for (int i = 0; i < exponente; i++)
    {
        resultado *= base;
    }

    return negativo ? 1 / resultado : resultado;
}
